54:   leftChain: FakeNode[];
55:   rightChain: FakeNode[];
56:   rightThumbChain: FakeNode[];
57:   leftThumbChain: FakeNode[];
58:   leftHand: FakeNode;
59:   rightHand: FakeNode;
60: } {
61:   const chain = (side: 'left' | 'right'): FakeNode[] => {
62:     const sign = side === 'left' ? 1 : -1;
63:     const foreArm = fakeNode({ x: 0.4 * sign, y: 0, z: 0 });
64:     const hand = fakeNode({ x: 0.5 * sign, y: 0, z: 0 }, foreArm);
65:     const p = fakeNode({ x: 0.6 * sign, y: 0, z: 0 }, hand);
66:     const i = fakeNode({ x: 0.7 * sign, y: 0, z: 0 }, p);
67:     const d = fakeNode({ x: 0.8 * sign, y: 0, z: 0 }, i);
68:     return [hand, p, i, d];
69:   };
70:   const [leftHand, leftP, leftI, leftD] = chain('left');
71:   const [rightHand, rightP, rightI, rightD] = chain('right');
72:   const leftLittle = fakeNode({ x: 0.6, y: 0.05, z: 0 }, leftHand); // left raw cross = +Z (into palm)
73:   const rightLittle = fakeNode({ x: -0.6, y: -0.05, z: 0 }, rightHand);
74:   // Thumb chains (metacarpal → proximal → distal), oblique off the hand.
75:   const rightThumbM = fakeNode({ x: -0.55, y: -0.1, z: 0 }, rightHand);
