80:   fakeNode({ x: 0.38, y: 0.18, z: 0 }, leftThumbP);
81:   const bones: Record<string, FakeNode> = {
82:     leftHand,
83:     rightHand,
84:     leftIndexProximal: leftP,
85:     leftIndexIntermediate: leftI,
86:     leftIndexDistal: leftD,
87:     rightIndexProximal: rightP,
88:     rightIndexIntermediate: rightI,
89:     rightIndexDistal: rightD,
90:     leftLittleProximal: leftLittle,
91:     rightLittleProximal: rightLittle,
92:     rightThumbMetacarpal: rightThumbM,
93:     rightThumbProximal: rightThumbP,
94:     leftThumbMetacarpal: leftThumbM,
95:     leftThumbProximal: leftThumbP,
96:   };
97:   const vrm = {
98:     humanoid: { getNormalizedBoneNode: (name: string) => bones[name] ?? null },
99:   } as unknown as VRM;
100:   const rightThumbChain = [rightThumbM, rightThumbP];
101:   const leftThumbChain = [leftThumbM, leftThumbP];
102:   return {
103:     vrm,
104:     leftChain: [leftP, leftI, leftD],
105:     rightChain: [rightP, rightI, rightD],
106:     rightThumbChain,
107:     leftThumbChain,
108:     leftHand,
109:     rightHand,
