1: /**
2:  * characterHand — palm + fingers of the stylized avatar hand.
3:  *
4:  * Rendered from the 21 tracked hand landmarks: a palm polygon (soft
5:  * rounded quad through wrist + knuckles) and tapered capsule finger
6:  * segments (wrist→mcp→pip→dip→tip). Thickness scales with the hand's own
7:  * knuckle span so proportions hold at any distance. Joints are implied by
8:  * the capsule geometry — no per-joint dots except subtle fingertips.
9:  */
10: 
11: import type { HandDetection } from '../../detection/types';
12: import { HAND_FINGERS } from '../../detection/handDetector';
13: import type { AvatarRig } from './characterRig';
14: import { COLOR_BODY, drawTaperedCapsule, roundedPolygonPath } from '../shapes';
15: import { distance } from '../../utils/geometry';
16: 
17: /** Fingertip landmark indices (thumb, index, middle, ring, pinky). */
18: const FINGERTIPS = [4, 8, 12, 16, 20] as const;
19: 
20: /** Finger widths relative to the palm chain (wrist→mcp = 1). */
21: const FINGER_WIDTHS = [0.85, 0.62, 0.52, 0.44] as const;
22: 
23: /**
24:  * Draws one tracked hand at the avatar's wrist.
25:  *
26:  * @param hand tracked 21-landmark hand (side already matched to the wrist)
27:  * @param handRadius fallback scale (avatar hand radius in px) for a
28:  *   momentarily degenerate knuckle span
29:  */
30: export function drawAvatarHand(
31:   ctx: CanvasRenderingContext2D,
32:   rig: AvatarRig,
36:   const px = hand.landmarks.map((lm) => rig.raw(`hand:${hand.side}:${lm.x.toFixed(3)}:${lm.y.toFixed(3)}`, lm));
37:   const span = distance(px[5], px[17]) || handRadius * 2;
38:   const seg = (a: { x: number; y: number }, b: { x: number; y: number }, w: number) =>
39:     drawTaperedCapsule(ctx, a, b, w, w * 0.78);
40: 
41:   // Palm: soft rounded quad through wrist, index MCP, ring-finger side
42:   // and pinky MCP — reads as a palm without heavy geometry.
43:   ctx.fillStyle = COLOR_BODY;
44:   roundedPolygonPath(ctx, [px[0], px[5], px[9], px[17]], span * 0.16);
45:   ctx.fill();
46: 
47:   // Palm base strokes (wrist → outer knuckles) blend palm into fingers.
48:   const w = span * 0.3;
49:   seg(px[0], px[5], w * 1.05);
50:   seg(px[0], px[17], w * 1.05);
51: 
52:   // Fingers (thumb chain included); each joint tapers toward the tip.
53:   for (const finger of HAND_FINGERS) {
54:     for (let i = 0; i < finger.length - 1; i += 1) {
55:       const width = w * FINGER_WIDTHS[Math.min(i, FINGER_WIDTHS.length - 1)];
56:       seg(px[finger[i]], px[finger[i + 1]], Math.max(width, w * 0.3));
57:     }
58:   }
59: 
60:   // Subtle fingertip caps for a readable silhouette.
61:   for (const tip of FINGERTIPS) {
62:     ctx.beginPath();
63:     ctx.arc(px[tip].x, px[tip].y, Math.max(w * 0.34, 1.5), 0, Math.PI * 2);
64:     ctx.fill();
65:   }
66: }

