46: bool GazeboGraspGripper::Init(physics::ModelPtr &_model,
47:                               const std::string &_gripperName,
48:                               const std::string &palmLinkName,
49:                               const std::vector<std::string> &fingerLinkNames,
50:                               bool _disableCollisionsOnAttach,
51:                               std::map<std::string, physics::CollisionPtr> &_collisionElems)
52: {
53:   this->gripperName = _gripperName;
54:   this->attached = false;
55:   this->disableCollisionsOnAttach = _disableCollisionsOnAttach;
56:   this->model = _model;
57:   physics::PhysicsEnginePtr physics =
58:     gazebo::GetPhysics(this->model->GetWorld());
59:   this->fixedJoint = physics->CreateJoint("revolute");
60: 
61:   this->palmLink = this->model->GetLink(palmLinkName);
62:   if (!this->palmLink)
63:   {
64:     gzerr << "GazeboGraspGripper: Palm link " << palmLinkName <<
65:           " not found. The gazebo grasp plugin will not work." << std::endl;
66:     return false;
67:   }
68:   for (std::vector<std::string>::const_iterator fingerIt =
69:          fingerLinkNames.begin();
70:        fingerIt != fingerLinkNames.end(); ++fingerIt)
71:   {
72:     physics::LinkPtr link = this->model->GetLink(*fingerIt);
73:     //gzmsg<<"Got link "<<fingerLinkElem->Get<std::string>()<<std::endl;
74:     if (!link.get())
75:     {
76:       gzerr << "GazeboGraspGripper ERROR: Link " << *fingerIt <<
77:             " can't be found in gazebo for GazeboGraspGripper model plugin. Skipping." <<
78:             std::endl;
79:       continue;
80:     }
81:     for (unsigned int j = 0; j < link->GetChildCount(); ++j)
82:     {
83:       physics::CollisionPtr collision = link->GetCollision(j);
84:       std::string collName = collision->GetScopedName();
85:       //collision->SetContactsEnabled(true);
86:       std::map<std::string, physics::CollisionPtr>::iterator collIter =
87:         collisionElems.find(collName);
88:       if (collIter !=
89:           this->collisionElems.end())   //this collision was already added before
90:       {
91:         gzwarn << "GazeboGraspGripper: Adding Gazebo collision link element " <<
92:                collName << " multiple times, the gazebo grasp handler may not work properly" <<
93:                std::endl;
94:         continue;
95:       }
96:       this->collisionElems[collName] = collision;
97:       _collisionElems[collName] = collision;
98:     }
99:   }
100:   return !this->collisionElems.empty();
101: }
