317:                     }
318:                     if (extensionType == SteamVR_Skeleton_FingerExtensionTypes.Extend)
319:                     {
320:                         // lerp to open pose by fingercurl
321:                         snapshot.bonePositions[boneIndex] = Vector3.Lerp(poseHand.bonePositions[boneIndex], skeletonAction.bonePositions[boneIndex], 1 - skeletonAction.fingerCurls[fingerIndex]);
