22: template <typename T>
23: std::vector<Eigen::Matrix4<T>> computeSkinningTransforms(
24:     typename DeduceSpanType<const JointStateT<T>>::type jointState,
25:     const TransformationListT<T>& inverseBindPose) {
26:   MT_CHECK(
27:       jointState.size() == inverseBindPose.size(),
28:       "{} vs {}",
29:       jointState.size(),
30:       inverseBindPose.size());
31: 
32:   std::vector<Eigen::Matrix4<T>> transforms(inverseBindPose.size());
33:   for (size_t i = 0; i < inverseBindPose.size(); i++) {
34:     transforms[i].noalias() = (jointState[i].transform * inverseBindPose[i]).matrix();
35:   }
36:   return transforms;
37: }
