46:   MT_CHECK(
47:       skin.index.rows() == static_cast<int>(points.size()),
48:       "{} vs {}",
49:       skin.index.rows(),
50:       points.size());
51:   MT_CHECK(
52:       skin.weight.rows() == static_cast<int>(points.size()),
53:       "{} vs {}",
54:       skin.weight.rows(),
55:       points.size());
56: 
57:   std::vector<Vector3<T>> result(points.size(), Vector3<T>::Zero());
58: 
59:   dispenso::ParForOptions options;
60:   options.minItemsPerChunk = 1024u;
61: 
62:   dispenso::parallel_for(
63:       dispenso::makeChunkedRange(0, skin.index.rows(), dispenso::ParForChunking::kAuto),
64:       [&](const size_t rangeBegin, const size_t rangeEnd) {
65:         for (size_t i = rangeBegin; i != rangeEnd; i++) {
66:           const Vector3<T>& pos = points[i];
67:           auto& output = result[i];
68:           output.setZero();
69: 
70:           // Unused influence slots are zero-filled (see `SkinWeights`); the first zero
71:           // weight terminates the active influences for this vertex.
72:           // TODO: This break assumes used slots are packed contiguously at the front
73:           // (no zero gaps before non-zero entries). `SkinWeights::set` enforces this
74:           // for ragged inputs, but other loaders may not — consider documenting the
75:           // invariant on `SkinWeights` or replacing the break with a continue.
76:           for (size_t j = 0; j < kMaxSkinJoints; j++) {
77:             const auto& weight = skin.weight(i, j);
78:             if (weight == 0.0f) {
79:               break;
80:             }
81: 
82:             MT_CHECK(
83:                 skin.index(i, j) < skinningTransforms.size(),
84:                 "skin.index({}, {}): {} vs {}",
85:                 i,
86:                 j,
87:                 skin.index(i, j),
88:                 skinningTransforms.size());
89:             const auto& transformation = skinningTransforms[skin.index(i, j)];
90: 
91:             // Equivalent to: output += (transformation * (pos, 1)) * weight,
92:             // expanded to avoid the homogeneous extension of `pos`.
93:             Eigen::Vector3<T> temp = transformation.template topRightCorner<3, 1>();
94:             temp.noalias() += transformation.template topLeftCorner<3, 3>() * pos;
95:             output.noalias() += temp * weight;
