15: 	public void UpdateKnuckleLanges() {
16: 		for (int i = 0; i < m_fingers.Length - 1; ++i) {
17: 			Vector3 start = m_fingers[i].GetComponent<LeapFinger>().GetJoint(0).transform.position;
18: 			Vector3 end = m_fingers[i + 1].GetComponent<LeapFinger>().GetJoint(0).transform.position;
19: 			m_knuckleLanges[i].transform.position = (start + end) * 0.5f;
20: 			m_knuckleLanges[i].transform.up = (start - end);
21: 			Vector3 newScale = m_knuckleLanges[i].transform.localScale;
22: 			newScale.y = Mathf.Max(0.0f, (start - end).magnitude - 0.003f);
23: 			m_knuckleLanges[i].transform.localScale = newScale;
24: 		}
25: 		// get the last joint by reflecting the mcb bone of the thumb
26: 		// across the hand direction.
27: 		Vector3 d = transform.position - m_fingers[0].GetComponent<LeapFinger>().GetJoint(0).transform.position;
28: 		Vector3 n = -transform.forward;
29: 		Vector3 r = d - (2 * Vector3.Dot(d, n)) * n;
30: 		m_wristJoint.transform.position = transform.position + r;
31: 		Vector3 pinkymcb = m_fingers[4].GetComponent<LeapFinger>().GetJoint(0).transform.position;
32: 		m_knuckleLanges[4].transform.position = (pinkymcb + m_wristJoint.transform.position) * 0.5f;
33: 		m_knuckleLanges[4].transform.up = (pinkymcb - m_wristJoint.transform.position);
34: 		Vector3 s = m_knuckleLanges[4].transform.localScale;
35: 		s.y = Mathf.Max(0.0f, (pinkymcb - m_wristJoint.transform.position).magnitude);
36: 		m_knuckleLanges[4].transform.localScale = s;
37: 
38: 		Vector3 thumbmcb = m_fingers[0].GetComponent<LeapFinger>().GetJoint(0).transform.position;
39: 		m_knuckleLanges[5].transform.position = (m_wristJoint.transform.position + thumbmcb) * 0.5f;
40: 		m_knuckleLanges[5].transform.up = (m_wristJoint.transform.position - thumbmcb);
41: 		s = m_knuckleLanges[5].transform.localScale;
42: 		s.y = Mathf.Max(0.0f, (m_wristJoint.transform.position - thumbmcb).magnitude);
43: 		m_knuckleLanges[5].transform.localScale = s;
44: 	}
