127: /** Per-digit curl phase — real fingers don't move in lockstep. */
128: export const DIGIT_PHASE = [0.0, 0.12, 0.24, 0.36, 0.18];
129: /** Thumb opposes rather than curls, and travels less. */
130: export const DIGIT_GAIN = [1.0, 0.98, 0.92, 0.82, 0.55];
131: 
132: /**
133:  * Drive one hand from a 0..1 "close" signal. Returns the mean curl so the
134:  * caller can light the force pods off the same number the fingers moved by.
135:  */
136: export function poseHand(hand: HandRig, close: number, t: number) {
137:   let sum = 0;
138:   for (const d of hand.digits) {
139:     const phase = DIGIT_PHASE[d.index] ?? 0;
140:     const gain = DIGIT_GAIN[d.index] ?? 1;
141:     // each finger lags the last a little, and never fully straightens
142:     const c = Math.max(0, Math.min(1, close - phase * 0.5)) * gain;
143:     // Kept deliberately shallow. Each digit is one rigid mesh, so a big
144:     // curl makes the straight flex channel punch through the glove — a
145:     // working-hand amount of motion reads true, a full fist does not.
146:     const curl = 0.04 + c * 0.34;
147:     d.group.rotation.x = -curl; // negative X curls toward the palm
148:     // fingers splay very slightly as they open
149:     d.group.rotation.y = (d.index - 1.5) * 0.015 * (1 - c) * (hand.side === "R" ? 1 : -1);
150:     sum += c;
151:   }
152:   void t;
153:   return hand.digits.length ? sum / hand.digits.length : 0;
154: }

