334:     /// <summary>Completes an otherwise reliable name map when the hand has clearly
335:     /// articulated child chains but their exporter-specific names carry no finger words.</summary>
336:     internal static void CompleteFingersByTopology(SkeletonModel skeleton, MappingResult result)
337:     {
338:         var children = BuildChildren(skeleton);
339:         var subtreeDepth = BuildSubtreeDepth(skeleton, children);
340:         var positions = skeleton.RestWorld.Select(x => x.Pos).ToArray();
341:         foreach (var side in new[] { "L", "R" })
342:         {
343:             if (!result.RoleToBone.TryGetValue(
344:                 Enum.Parse<BoneRole>("Hand" + side), out var hand))
345:                 continue;
346:             var inferred = new MappingResult("topology", MappingSource.AutoTopology);
347:             MapFingersByTopology(inferred, skeleton, children, subtreeDepth, positions, hand, side);
348:             // Fill only entirely missing chains. Existing profile/name assignments win,
349:             // and a bone already assigned to another digit must never be reused.
350:             foreach (var finger in new[] { "Thumb", "Index", "Middle", "Ring", "Pinky" })
351:             {
352:                 var chain = inferred.RoleToBone.Where(p => p.Key.ToString().StartsWith(finger)
353:                     && p.Key.ToString().EndsWith(side)).ToArray();
354:                 if (result.RoleToBone.Keys.Any(r => r.ToString().StartsWith(finger)
355:                     && r.ToString().EndsWith(side))
356:                     || chain.Any(p => result.RoleToBone.ContainsValue(p.Value)))
357:                     continue;
358:                 foreach (var pair in chain)
359:                     result.RoleToBone.Add(pair.Key, pair.Value);
360:             }
361:         }
362:     }
