8: namespace HumanoidRetargeter.Solve;
9: 
10: using Vector3 = System.Numerics.Vector3; // s&box compat: shadow engine's global-namespace Vector3 (see Code/HumanoidRetargeter/Assembly.cs)
11: 
12: /// <summary>
13: /// Hand rest-geometry helpers shared by <see cref="CanonicalFrames"/> (finger secondary axes)
14: /// and <see cref="RestNormalizer"/> (palm-down roll correction). Everything derives from joint
15: /// positions only — bone local axes carry no anatomical meaning on the s&amp;box rig.
16: /// </summary>
17: internal static class HandGeometry
18: {
19:     private static readonly BoneRole[] LeftProximals =
20:     {
21:         BoneRole.ThumbProxL, BoneRole.IndexProxL, BoneRole.MiddleProxL, BoneRole.RingProxL, BoneRole.PinkyProxL,
22:     };
23: 
24:     private static readonly BoneRole[] RightProximals =
25:     {
26:         BoneRole.ThumbProxR, BoneRole.IndexProxR, BoneRole.MiddleProxR, BoneRole.RingProxR, BoneRole.PinkyProxR,
27:     };
28: 
29:     // Index → pinky order; the knuckle line is taken from the first and last mapped of these.
30:     private static readonly BoneRole[] LeftNonThumbProximals =
31:     {
32:         BoneRole.IndexProxL, BoneRole.MiddleProxL, BoneRole.RingProxL, BoneRole.PinkyProxL,
33:     };
34: 
35:     private static readonly BoneRole[] RightNonThumbProximals =
36:     {
37:         BoneRole.IndexProxR, BoneRole.MiddleProxR, BoneRole.RingProxR, BoneRole.PinkyProxR,
38:     };
39: 
40:     /// <summary>
41:     /// Midpoint of all mapped finger proximal heads of one hand (the hand's anatomical
42:     /// "chain child" point), or null when no finger proximal is mapped.
43:     /// </summary>
44:     public static Vector3? FingerProximalMidpoint(MappingResult map, IReadOnlyList<XForm> worldRest, bool left)
45:     {
46:         var sum = Vector3.Zero;
47:         var count = 0;
48:         foreach (var role in left ? LeftProximals : RightProximals)
49:         {
50:             if (map.RoleToBone.TryGetValue(role, out var index))
51:             {
52:                 sum += worldRest[index].Pos;
53:                 count++;
54:             }
55:         }
56:         return count > 0 ? sum / count : null;
57:     }
58: 
59:     /// <summary>
60:     /// Dorsal palm normal of one hand: the unit vector pointing out of the <b>back</b> of the
61:     /// hand (away from the palm), or null when the hand/finger geometry is unmapped or
62:     /// degenerate.
63:     /// </summary>
64:     /// <remarks>
65:     /// Formula (mirror-consistent by construction, verified on the ActorCore fixture by the
66:     /// finger-curl test): <c>dorsal = sideSign · cross(knuckle, fingerDir)</c> with
67:     /// <c>sideSign = +1</c> left / <c>−1</c> right, <c>knuckle = IndexProx.head −
68:     /// PinkyProx.head</c> (first/last mapped non-thumb proximal), and <c>fingerDir =
69:     /// FingerProximalMidpoint − Hand.head</c>. On every fixture rig the thumb proximal lies on
70:     /// the −dorsal (palmar) side of the hand plane, grounding the sign anatomically. A positive
71:     /// rotation about a finger frame's hinge axis (frame Y = cross(dorsal, fingerChainDir))
72:     /// curls the fingertip toward the palm on <b>both</b> hands.
73:     /// </remarks>
74:     public static Vector3? Dorsal(MappingResult map, IReadOnlyList<XForm> worldRest, bool left)
75:     {
76:         if (!map.RoleToBone.TryGetValue(left ? BoneRole.HandL : BoneRole.HandR, out var handIndex))
77:             return null;
78:         var hand = worldRest[handIndex].Pos;
79: 
80:         var nonThumb = left ? LeftNonThumbProximals : RightNonThumbProximals;
81:         Vector3? first = null, last = null;
82:         foreach (var role in nonThumb)
83:         {
84:             if (!map.RoleToBone.TryGetValue(role, out var index))
85:                 continue;
86:             first ??= worldRest[index].Pos;
87:             last = worldRest[index].Pos;
88:         }
89:         if (first is null || last is null || (first.Value - last.Value).LengthSquared() < 1e-8f)
90:             return null;
91: 
92:         var midpoint = FingerProximalMidpoint(map, worldRest, left);
93:         if (midpoint is null)
94:             return null;
95: 
96:         var knuckle = first.Value - last.Value;
97:         var fingerDir = midpoint.Value - hand;
98:         var raw = Vector3.Cross(knuckle, fingerDir) * (left ? 1f : -1f);
99:         return raw.LengthSquared() < 1e-8f ? null : Vector3.Normalize(raw);
100:     }
101: }

